import boto3

def check_payload(payload):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(
        Text=payload,
        LanguageCode='en'
    )
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return 'Unsafe'
    else:
        return 'Safe'

import boto3

def summarize_key_usage():
    client = boto3.client('cloudtrail')
    response = client.lookup_events(
       LookupAttributes=[
           {
               'AttributeKey': 'EventName',
               'AttributeValue': 'Decrypt'
           }
       ]
   )
    events = response['Events']
    key_usage_summary = {}
    for event in events:
        event_name = event['EventName']
        if event_name not in key_usage_summary:
            key_usage_summary[event_name] = 0
        key_usage_summary[event_name] += 1
    return key_usage_summary

if __name__ == '__main__':
    summary = summarize_key_usage()
    print(summary)

from typing import Any, Dict

import boto3


def create_key():
    client = boto3.client('kms')
    response = client.create_key()
    return response


def encrypt_data(key_id: str, plaintext: bytes):
    client = boto3.client('kms')
    response = client.encrypt(KeyId=key_id, Plaintext=plaintext)
    return response


def decrypt_data(ciphertext_blob: bytes):
    client = boto3.client('kms')
    response = client.decrypt(CiphertextBlob=ciphertext_blob)
    return response


def normalize_response(response: Dict[str, Any]) -> Dict[str, Any]:
    normalized_response = {}
    for key, value in response.items():
        if isinstance(value, bytes):
            normalized_response[key] = value.decode('utf-8')
        else:
            normalized_response[key] = value
    return normalized_response
